import './style.css';
import './modern.css';
import './operations.css';
import './accounts.css';
import {selectProducts,dashboardStats,ordersCsv,productPayload} from './features.js';
import { createClient } from '@supabase/supabase-js';
import { demoProducts } from './catalogue.js';
const url=import.meta.env.VITE_SUPABASE_URL, key=import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
const sb=url&&key?createClient(url,key):null;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR',maximumFractionDigits:2}).format(c/100);
const image=s=>{try{const u=new URL(s,location.origin);return ['https:','http:'].includes(u.protocol)?esc(u.href):'/images/bob.svg'}catch{return '/images/bob.svg'}};
let products=[], demo=false, category='All', search='', session=null, shipping=8000, ready=false;
sb?.auth.onAuthStateChange((_event,next)=>{session=next});
let cart;try{cart=JSON.parse(localStorage.getItem('hairluke-cart')||'[]');if(!Array.isArray(cart))cart=[];cart=cart.filter(i=>typeof i.id==='string'&&Number.isInteger(i.qty)&&i.qty>0&&i.qty<=20)}catch{cart=[]}
function toast(message){let el=$('#toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.add('hidden'),3500)}
function saveCart(){localStorage.setItem('hairluke-cart',JSON.stringify(cart));$('#cart-count').textContent=cart.reduce((n,i)=>n+i.qty,0)}
function base(){return `<div class="announcement"><span>YOUR NEXT GOOD HAIR DAY STARTS HERE.</span><span class="announcement-right">South Africa · Your next signature look</span></div><header><a class="brand" href="/">hairluke<span>.</span></a><nav id="mobile-navigation" aria-label="Main navigation"><a href="/#collection">The collection</a><a href="/#story">Our world</a><a href="/#care">Hair rituals</a><a class="mobile-only-link" href="/try-on">Colour studio</a><a class="mobile-only-link" href="/orders">My orders</a><a class="mobile-only-link" href="/account">Log in / Sign up</a></nav><div class="header-actions"><a class="header-icon" href="/account" aria-label="My account: log in or sign up"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg></a><a class="header-tryon" href="/try-on" aria-label="Free hair colour preview">${icon('spark')}<span>Colour studio</span></a><a class="header-icon header-track" href="/orders" aria-label="My orders">${icon('box')}</a><button class="header-icon" id="open-favourites" aria-label="Saved favourites">${icon('heart')}<span id="favourite-count">${favourites.length}</span></button><button class="cart-button" id="open-cart">${icon('bag')}<span>Bag (<span id="cart-count">0</span>)</span></button><button id="mobile-menu-toggle" class="mobile-menu-button" aria-label="Open menu" aria-expanded="false" aria-controls="mobile-navigation"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path class="menu-lines" d="M3 6h18M3 12h18M3 18h18"/><path class="menu-cross" d="m5 5 14 14M19 5 5 19"/></svg></button></div></header><main id="main"></main><footer><div class="footer-intro"><a href="/" class="brand">hairluke<span>.</span></a><p>Good hair. Unapologetically you.</p><span class="eyebrow">FIND YOUR EVERYDAY EXTRAORDINARY.</span></div><div><h3>Explore</h3><a href="/#collection">Shop the collection</a><a href="/try-on">Free colour preview</a><a href="/#care">Hair care guide</a><a href="/orders">My orders</a></div><div><h3>Here to help</h3><a href="/policies">Delivery & returns</a><a id="contact-email" href="mailto:tumzena@gmail.com">tumzena@gmail.com</a><a href="/admin">Store studio</a></div><div class="footer-bottom"><p>© ${new Date().getFullYear()} Hairluke. Your style, your story.</p><p>Secure payments with Yoco · ZAR</p></div></footer><div id="toast" class="toast hidden" role="status"></div><dialog id="cart-dialog" aria-labelledby="bag-title"><div class="dialog-inner"><div class="dialog-top"><div><span class="eyebrow">A LITTLE SOMETHING FOR YOU</span><h2 id="bag-title">Your bag.</h2></div><button class="close" id="close-cart" aria-label="Close bag">×</button></div><div id="bag-content"></div></div></dialog><dialog id="product-dialog" aria-labelledby="detail-title"><button class="close detail-close" id="close-product" aria-label="Close product details">×</button><div id="product-detail"></div></dialog>`}
function storefront(){ $('#main').innerHTML=`<div id="store-notice" class="notice hidden" role="status"></div><section class="hero"><div class="hero-copy"><span class="eyebrow"><span class="tiny-star">✳</span> THE HAIRLUKE EDIT</span><h1>A whole<br>new kind<br>of <em>you.</em></h1><p>New look. Same main character.<br>Find your signature in our collection of wigs, bundles and finishing touches.</p><div class="hero-buttons"><a class="primary" href="#collection">Find your look ${icon('arrow')}</a><a class="text-link" href="#story">Meet Hairluke ↗</a></div><div class="hero-footnote"><span class="mini-line"></span><span>GOOD HAIR IS A FEELING.<br>MAKE IT YOURS.</span></div></div><div class="hero-art"><img src="/images/editorial-hero.png" alt="Editorial portrait celebrating long, flowing hair" fetchpriority="high"><div class="hero-label"><span>THE EVERYDAY, REIMAGINED.</span><strong>Wear your confidence.</strong></div><span class="vertical-label">HAIRLUKE / YOUR SIGNATURE LOOK</span></div><div class="hero-stamp" aria-hidden="true">YOUR HAIR<br><span>YOUR RULES ↗</span></div></section><div class="benefits"><span>${icon('spark')} A look for every version of you</span><span>${icon('box')} Delivery, clearly priced at checkout</span><span>${icon('check')} Secure payments with Yoco</span></div><section class="section collection-section" id="collection"><div class="section-heading"><div><span class="eyebrow">THE GOOD HAIR CLUB</span><h2>Your next signature.</h2></div><p>Find a little more you.<br>Explore by style, texture and mood.</p></div><div class="filters">${['All','Wigs','Bundles','Closures'].map(c=>`<button class="filter ${c===category?'active':''}" data-category="${c}">${c==='All'?'All looks':c}</button>`).join('')}<label class="search-wrap">${icon('search')}<input class="search" id="search" aria-label="Search products" placeholder="Search your next look" type="search"></label></div><div class="collection-tools"><span id="result-count" class="small"></span><div><select id="texture-filter" aria-label="Filter texture"><option value="All">All textures</option></select><select id="sort-products" aria-label="Sort products"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name: A–Z</option></select><label class="stock-toggle"><input type="checkbox" id="in-stock"> In stock</label><button id="saved-filter" class="text-link ${savedOnly?'selected':''}">${icon('heart')} ${savedOnly?'Showing saved':'Saved looks'}</button></div></div><div class="grid" id="products"><p class="empty">Finding your next favourite…</p></div><div class="tryon-callout"><div><span class="eyebrow">CURIOUS ABOUT COLOUR?</span><h3>Meet another side of you.</h3><p>Preview a different shade on your own hair, free in your browser. Your photo stays on your device.</p></div><a class="primary" href="/try-on">Explore the colour studio ${icon('arrow')}</a></div></section><section id="story" class="section story"><div class="story-visual"><span class="eyebrow">THE HAIRLUKE PHILOSOPHY</span><span class="story-mark">More than<br><em>good hair.</em></span><span class="story-bottom">A LITTLE CONFIDENCE CHANGES EVERYTHING.</span></div><div class="story-copy"><span class="eyebrow">YOUR LOOK. YOUR LANGUAGE.</span><h2>Show up.<br>As <em>yourself.</em></h2><p>Some days call for soft waves. Others, a sleek new chapter. Hairluke is a space to explore the looks that make you feel most like you.</p><p>No rules to fit into. Just a collection to make your own.</p><a class="primary" href="#collection">Explore your possibilities ${icon('arrow')}</a></div></section><section id="care" class="section"><div class="section-heading"><div><span class="eyebrow">THE EVERYDAY RITUAL</span><h2>Good hair. Better care.</h2></div><p>A little love goes a long way.</p></div><div class="care"><article><span class="number">01 — DETANGLE</span><h3>Keep it gentle.</h3><p>Start at the ends and work upwards with a suitable brush or wide-tooth comb. Follow the guidance for your specific hair type.</p></article><article><span class="number">02 — CLEANSE</span><h3>Make it a ritual.</h3><p>Use products suited to your wig or extensions. Wash gently and let your hair dry completely before storing.</p></article><article><span class="number">03 — PROTECT</span><h3>Give it a good rest.</h3><p>Keep hair neatly stored away from heat and moisture. Check your product’s heat guidance before styling.</p></article></div></section><section class="section faq-section"><div><span class="eyebrow">A FEW GOOD ANSWERS</span><h2>Before you<br><em>make it yours.</em></h2><a class="text-link" href="mailto:tumzena@gmail.com" id="help-email">Still curious? Get in touch ↗</a></div><div class="faq-list"><details><summary>How do I choose my length and texture?</summary><p>Open a product’s quick view to see its length, texture and colour. Each listed product represents a specific combination. Compare the options in the collection or contact us for help.</p></details><details><summary>How much does delivery cost?</summary><p>Standard delivery is <span id="faq-delivery">${money(shipping)}</span>, shown in your bag before payment. Check our delivery information for coverage and timing.</p></details><details><summary>How can I track my order?</summary><p>Log in to <a href="/orders">My orders</a> to follow payment, preparation, dispatch and delivery. Use the same verified email as your checkout. If you checked out as a guest, create an account with that email.</p></details><details><summary>How do payments work?</summary><p>Hairluke sends you to Yoco’s secure checkout. Your order is marked paid only after a verified payment confirmation.</p></details><details><summary>Can I return an order?</summary><p>Read our <a href="/policies">returns and delivery information</a> before ordering, and contact the shop with your order reference if you need assistance.</p></details></div></section><section class="closing-banner"><span class="eyebrow">YOUR NEXT CHAPTER LOOKS GOOD ON YOU.</span><h2>Make an entrance.</h2><a class="primary" href="#collection">Shop the collection ${icon('arrow')}</a></section>`;
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));renderProducts()});$('#search').oninput=e=>{search=e.target.value.toLowerCase();renderProducts()};$('#sort-products').onchange=e=>{sortOrder=e.target.value;renderProducts()};$('#texture-filter').onchange=e=>{textureFilter=e.target.value;renderProducts()};$('#in-stock').onchange=e=>{stockOnly=e.target.checked;renderProducts()};$('#saved-filter').onclick=()=>{savedOnly=!savedOnly;renderProducts()};loadProducts()}
async function loadProducts(){try{if(!sb)throw Error('missing configuration');const {data,error}=await sb.from('products').select('*').eq('active',true).order('created_at');if(error)throw error;products=data;demo=false;if(!products.length){$('#store-notice').textContent='The collection is being prepared. Please check back soon.';$('#store-notice').classList.remove('hidden')}}catch{products=demoProducts;demo=true;$('#store-notice').textContent='Preview collection — illustrative products, prices and artwork. Online orders are not enabled for these samples.';$('#store-notice').classList.remove('hidden')}catalogueLoaded=true;const textureSelect=$('#texture-filter');textureSelect.innerHTML='<option value="All">All textures</option>'+[...new Set(products.map(p=>p.texture))].sort().map(t=>'<option value="'+esc(t)+'">'+esc(t)+'</option>').join('');renderProducts();if($('#cart-dialog').open)bag();try{const c=await api('/api/config');shipping=c.shipping_cents;ready=c.checkout_ready;$('#contact-email').textContent=c.contact_email;$('#contact-email').href='mailto:'+c.contact_email;if($('#help-email'))$('#help-email').href='mailto:'+c.contact_email;if($('#faq-delivery'))$('#faq-delivery').textContent=money(shipping);if($('#cart-dialog').open)bag()}catch{ready=false}}
function renderProducts(){const list=selectProducts(products,{category,search,texture:textureFilter,sort:sortOrder,inStock:stockOnly,savedOnly,favourites});$('#products').innerHTML=list.length?list.map(p=>`<article class="product"><div class="product-image"><button class="image-button" data-detail="${esc(p.id)}" aria-label="View ${esc(p.name)}"><img src="${image(p.image_url)}" alt="${esc(p.name)}" loading="lazy"></button><span class="badge">${esc(p.category)}</span><button class="favourite ${favourites.includes(p.id)?'is-saved':''}" data-fav="${esc(p.id)}" aria-label="${favourites.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${favourites.includes(p.id)}">${icon('heart')}</button><button class="quick-view" data-detail="${esc(p.id)}">Quick view ↗</button></div><div class="product-info"><div><p class="product-kicker">${esc(p.texture)} / ${esc(p.length)}</p><h3><button data-detail="${esc(p.id)}">${esc(p.name)}</button></h3><p>${esc(p.colour)}</p></div><span class="price">${money(p.price_cents)}</span></div><button class="add" data-add="${esc(p.id)}" ${p.stock<1?'disabled':''}>${p.stock<1?'Currently sold out':'Add to bag'} ${p.stock<1?'':icon('bag')}</button>${p.stock>0&&p.stock<=5?'<span class="low-stock-note">Only '+p.stock+' left</span>':''}</article>`).join(''):`<div class="empty"><span>${icon(savedOnly?'heart':'search')}</span><h3>${savedOnly?'Your favourites start here.':'No looks found.'}</h3><p>${savedOnly?'Tap the heart on a product to save it for later.':'Try a different search or clear your filters.'}</p><button class="primary" id="clear-filters">Explore all looks</button></div>`;
$('#result-count').textContent=list.length+' look'+(list.length===1?'':'s')+(savedOnly?' saved':' to make your own');$('#saved-filter').classList.toggle('selected',savedOnly);$('#saved-filter').innerHTML=icon('heart')+(savedOnly?'Showing saved':'Saved looks');document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addToCart(b.dataset.add));document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>toggleFavourite(b.dataset.fav));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>productDetail(b.dataset.detail));if($('#clear-filters'))$('#clear-filters').onclick=()=>{category='All';search='';textureFilter='All';savedOnly=false;stockOnly=false;$('#search').value='';$('#texture-filter').value='All';$('#in-stock').checked=false;document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category==='All'));renderProducts()};}
function bag(){if(!catalogueLoaded){$('#bag-content').innerHTML='<p class="status">Loading your bag…</p>';return}let items=cart.map(i=>({...i,p:products.find(p=>p.id===i.id)})).filter(i=>i.p);cart=items.map(({id,qty})=>({id,qty}));saveCart();const subtotal=items.reduce((n,i)=>n+i.qty*i.p.price_cents,0);$('#bag-content').innerHTML=items.length?`${items.map(i=>`<div class="cart-row"><img src="${image(i.p.image_url)}" alt=""><div><h3>${esc(i.p.name)}</h3><p>${esc(i.p.length)} · ${esc(i.p.colour)}</p><div class="qty"><button data-qty="${esc(i.id)}" data-step="-1" aria-label="Reduce quantity">−</button><span>${i.qty}</span><button data-qty="${esc(i.id)}" data-step="1" aria-label="Increase quantity">+</button><button class="remove" data-remove="${esc(i.id)}">Remove</button></div></div><span class="price">${money(i.qty*i.p.price_cents)}</span></div>`).join('')}<div class="totals"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><p class="small">${shipping===null?'Delivery pricing is being finalised.':`Delivery: ${money(shipping)}. Total: ${money(subtotal+(shipping||0))}.`}</p><h3>Checkout</h3>${session?.user?`<p class="small">Your order will appear in My orders for <strong>${esc(session.user.email)}</strong>.</p>`:`<p class="notice"><a href="/account">Log in or sign up</a> to keep purchases in My orders. For guest checkout, create an account later using the exact email entered below.</p>`}${demo?'<div class="notice" id="checkout-availability">These are sample products. Add real products in the admin area before accepting orders.</div>':!ready?'<div class="notice" id="checkout-availability">You can review checkout below. Payment is not available yet while we finish the Yoco setup.</div>':''}<form id="checkout" class="checkout-form"><label>Full name<input name="name" autocomplete="name" required maxlength="120"></label><label>Email<input name="email" type="email" autocomplete="email" required maxlength="200" value="${esc(session?.user?.email||'')}" ${session?.user?'readonly':''}></label><label>Phone<input name="phone" autocomplete="tel" required maxlength="30"></label><label>Street address<input name="address" autocomplete="street-address" required maxlength="250"></label><label>City<input name="city" autocomplete="address-level2" required maxlength="100"></label><label>Province<input name="province" autocomplete="address-level1" required maxlength="100"></label><label>Postal code<input name="postal_code" autocomplete="postal-code" required pattern="[0-9]{4}" maxlength="4"></label><label>Country<input value="South Africa" readonly></label><label class="wide"><span><input type="checkbox" required> I agree to the <a href="/policies" target="_blank" rel="noopener">delivery, returns and privacy terms</a>.</span></label><button class="primary wide" type="submit" ${demo||!ready?'disabled aria-describedby="checkout-availability"':''}>Pay with Yoco · ${money(subtotal+(shipping||0))}</button><p id="checkout-message" class="status wide" role="status"></p></form>`:'<p class="status">Your bag is waiting for a little hair happiness.</p><button class="primary" id="continue-shopping">Explore the collection</button>';
document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const i=cart.find(x=>x.id===b.dataset.qty),p=products.find(x=>x.id===i.id);i.qty=Math.max(0,Math.min(Math.min(20,p.stock),i.qty+Number(b.dataset.step)));cart=cart.filter(i=>i.qty);bag()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart=cart.filter(i=>i.id!==b.dataset.remove);bag()});if($('#continue-shopping'))$('#continue-shopping').onclick=()=>$('#cart-dialog').close();if($('#checkout'))$('#checkout').onsubmit=async e=>{e.preventDefault();if(demo||!ready)return toast('Payments are not enabled yet.');const button=e.target.querySelector('button[type=submit]');button.disabled=true;$('#checkout-message').textContent='Preparing your secure checkout…';try{const result=await api('/api/checkout',{method:'POST',body:{items:cart,expected_total:subtotal+shipping,customer:Object.fromEntries(new FormData(e.target))}});sessionStorage.setItem('hairluke-order',result.token);rememberOrder(result.token);location.assign(result.redirectUrl)}catch(err){$('#checkout-message').textContent=err.message;button.disabled=false}}}
async function api(path,options={}){const res=await fetch(path,{method:options.method||'GET',headers:{'Content-Type':'application/json',...(session?{Authorization:'Bearer '+session.access_token}:{})},...(options.body?{body:JSON.stringify(options.body)}:{})});const data=await res.json();if(!res.ok)throw Error(data.error||'Something went wrong. Please try again.');return data}
async function payment(){const params=new URLSearchParams(location.search),token=params.get('order')||sessionStorage.getItem('hairluke-order');$('#main').innerHTML='<section class="payment-card"><span class="eyebrow">Your Hairluke order</span><h1>Checking your payment</h1><p id="payment-status" role="status">Waiting for payment confirmation…</p><a class="primary" href="/orders">View my orders</a><p class="small">Log in or create an account using your checkout email to follow your delivery.</p><a class="text-link" href="/">Continue shopping</a></section>';if(params.get('result')==='cancelled'||params.get('result')==='failed'){$('#payment-status').textContent='Checkout was cancelled or unsuccessful. Your order has not been marked as paid. You can return to your bag to try again.';return}if(!token){$('#payment-status').textContent='No order reference was found. Please contact the shop if you completed a payment.';return}let attempts=0;rememberOrder(token);const poll=async()=>{try{const result=await api('/api/orders/'+encodeURIComponent(token));if(['paid','processing','shipped','delivered'].includes(result.status)){$('#payment-status').textContent='Payment confirmed. Thank you! Your order reference is '+result.id+'.';cart=[];saveCart();return}$('#payment-status').textContent='Payment confirmation is still pending. Keep your order reference: '+result.id+'.'}catch(err){$('#payment-status').textContent=err.message}if(++attempts<12)setTimeout(poll,5000)};poll()}
async function admin(){if(!sb){$('#main').innerHTML='<p class="notice">Supabase configuration is missing.</p>';return}session=(await sb.auth.getSession()).data.session;if(!session){$('#main').innerHTML=`<section class="admin"><h1>Store studio.</h1><p class="small">Sign in with your authorised Hairluke admin account.</p><form id="login" class="admin-card checkout-form"><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">Sign in</button><p id="login-message" role="status"></p></form></section>`;$('#login').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target);const {error}=await sb.auth.signInWithPassword({email:d.get('email'),password:d.get('password')});if(error)$('#login-message').textContent='Sign-in failed. Check your email and password.';else admin()};return}
$('#main').innerHTML=`<section class="admin"><div class="admin-toolbar"><h1>Store studio.</h1><button id="logout">Sign out</button></div><p id="admin-status" class="status" role="status">Loading…</p><div id="admin-content"></div></section>`;$('#logout').onclick=async()=>{await sb.auth.signOut();session=null;admin()};try{const data=await api('/api/admin');$('#admin-status').textContent='Manage your collection and fulfil paid orders.';$('#admin-content').innerHTML=`<div class="admin-card"><h2>Shop settings</h2><form id="settings-form" class="checkout-form"><label>Delivery fee (rand)<input name="delivery" type="number" min="0" max="10000" step="0.01" required value="${data.settings.shipping_cents/100}"></label><label>Customer contact email<input name="contact" type="email" required value="${esc(data.settings.contact_email)}"></label><button class="primary" type="submit">Save shop settings</button><p id="settings-message" role="status"></p></form></div><div class="admin-card"><h2>Product editor</h2><form id="product-form" class="product-form"><input type="hidden" name="id"><label>Name<input name="name" required maxlength="120"></label><label>Category<select name="category"><option>Wigs</option><option>Bundles</option><option>Closures</option></select></label><label>Texture<input name="texture" required maxlength="60"></label><label>Length<input name="length" required maxlength="40" placeholder="18 inch"></label><label>Colour<input name="colour" required maxlength="60"></label><label>Price (rand)<input name="price" type="number" step="0.01" min="2" max="100000" required></label><label>Stock<input name="stock" type="number" min="0" max="100000" required></label><label>Image URL<input name="image_url" type="url" placeholder="https://…"></label><label class="wide">Upload photo<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="wide">Description<textarea name="description" maxlength="1500"></textarea></label><label><span><input type="checkbox" name="active" checked> Visible in shop</span></label><div class="wide admin-toolbar"><button type="submit" class="primary">Save product</button><button type="button" id="reset-product">New product</button></div><p id="save-message" role="status" class="wide"></p></form></div><div class="admin-card admin-list"><h2>Collection</h2><table><thead><tr><th>Name</th><th>Price</th><th>Stock</th><th>Visible</th><th></th></tr></thead><tbody>${data.products.map(p=>`<tr><td>${esc(p.name)} · ${esc(p.length)}</td><td>${money(p.price_cents)}</td><td>${p.stock}</td><td>${p.active?'Yes':'No'}</td><td><button data-edit="${p.id}">Edit</button></td></tr>`).join('')}</tbody></table></div><div class="admin-card admin-list"><h2>Recent orders</h2><p class="small">Only paid orders can be marked shipped. Process refunds in Yoco; reconcile any refunds here before changing stock.</p><table><thead><tr><th>Reference</th><th>Customer</th><th>Items / delivery</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${data.orders.map(o=>`<tr><td>${esc(o.id)}</td><td>${esc(o.customer.name)}<br>${esc(o.customer.email)}<br>${esc(o.customer.phone)}</td><td>${o.items.map(i=>esc(i.name)+' × '+i.qty).join('<br>')}<br>${esc([o.customer.address,o.customer.city,o.customer.province,o.customer.postal_code].join(', '))}</td><td>${money(o.total_cents)}</td><td>${esc(o.status)}${o.payment_mode==='test'?' (TEST)':''}</td><td>${o.status==='paid'&&o.payment_mode==='live'?`<button data-ship="${o.id}">Mark shipped</button>`:''}</td></tr>`).join('')}</tbody></table>${data.orders.length?'':'<p>No orders yet.</p>'}</div>`;
$('#settings-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const d=new FormData(e.target);await api('/api/admin/settings',{method:'POST',body:{shipping_cents:Math.round(Number(d.get('delivery'))*100),contact_email:d.get('contact')}});$('#settings-message').textContent='Shop settings saved.'}catch(err){$('#settings-message').textContent=err.message}finally{button.disabled=false}};
enhanceAdmin(data);enhanceOperations(data);
const form=$('#product-form');$('#reset-product').onclick=()=>{form.reset();form.elements.id.value=''};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const p=data.products.find(p=>p.id===b.dataset.edit);for(const k of ['id','name','category','texture','length','colour','stock','image_url','description'])form.elements[k].value=p[k]||'';form.elements.price.value=p.price_cents/100;form.elements.active.checked=p.active;form.scrollIntoView({behavior:'smooth'})});form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;$('#save-message').textContent='Saving…';try{const d=new FormData(form);let imageUrl=d.get('image_url');const photo=d.get('photo');if(photo?.size){if(!['image/jpeg','image/png','image/webp'].includes(photo.type)||photo.size>5*1024*1024)throw Error('Choose a JPG, PNG or WebP image under 5 MB.');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[photo.type];const name=crypto.randomUUID()+'.'+ext;const {error}=await sb.storage.from('product-images').upload(name,photo);if(error)throw error;imageUrl=sb.storage.from('product-images').getPublicUrl(name).data.publicUrl}await api('/api/admin/products',{method:'POST',body:{id:d.get('id')||undefined,name:d.get('name'),category:d.get('category'),texture:d.get('texture'),length:d.get('length'),colour:d.get('colour'),stock:Number(d.get('stock')),price_cents:Math.round(Number(d.get('price'))*100),image_url:imageUrl||'/images/bob.svg',description:d.get('description'),active:d.get('active')==='on'}});await admin();toast('Product saved.')}catch(err){$('#save-message').textContent=err.message;button.disabled=false}};document.querySelectorAll('[data-ship]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/admin/orders/'+b.dataset.ship,{method:'PATCH',body:{status:'shipped'}});await admin()}catch(err){toast(err.message);b.disabled=false}})
}catch(err){$('#admin-status').textContent=err.message}}
function policies(){$('#main').innerHTML=`<article class="policy"><span class="eyebrow">Shop information</span><h1>Delivery, returns & privacy</h1><div class="notice">Store setup in progress. These draft terms must be completed by the store owner before checkout is enabled.</div><h2>Delivery</h2><p>Standard delivery: <span id="policy-shipping">R80.00</span>. Delivery coverage and estimated delivery times must be confirmed before launch.</p><h2>Returns & refunds</h2><p>The store owner must publish a return contact, return process, applicable timelines and conditions for wigs and extensions. Any hygiene restrictions must be explained alongside applicable consumer rights.</p><h2>Your information</h2><p>Checkout collects your name, email, telephone number and delivery address to process and deliver orders. Order data is stored using Supabase. Yoco handles card payments; Hairluke does not collect or store your card number.</p><p>The owner must add business contact details, retention periods and a process for privacy requests before launch.</p><h2>Contact</h2><p><a id="policy-contact" href="mailto:tumzena@gmail.com">tumzena@gmail.com</a></p></article>`}
const icon=(name)=>{const paths={bag:'<path d="M6 7h12l1 13H5L6 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',box:'<path d="m3 7 9-5 9 5v10l-9 5-9-5Z"/><path d="m3 7 9 5 9-5M12 12v10"/>',check:'<path d="m5 12 4 4L19 6"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.arrow}</svg>`};
let textureFilter='All',sortOrder='featured',stockOnly=false,savedOnly=new URLSearchParams(location.search).get('saved')==='1',catalogueLoaded=false;
let favourites;try{favourites=JSON.parse(localStorage.getItem('hairluke-favourites')||'[]');if(!Array.isArray(favourites))favourites=[];favourites=favourites.filter(x=>typeof x==='string')}catch{favourites=[]}
function toggleFavourite(id){favourites=favourites.includes(id)?favourites.filter(x=>x!==id):[...favourites,id];localStorage.setItem('hairluke-favourites',JSON.stringify(favourites));$('#favourite-count').textContent=favourites.length;renderProducts();const b=document.querySelector('#product-detail [data-detail-fav]');if(b&&b.dataset.detailFav===id){b.setAttribute('aria-pressed',String(favourites.includes(id)));b.innerHTML=icon('heart')+(favourites.includes(id)?'Saved to favourites':'Save this look')}}
function addToCart(id){const p=products.find(p=>p.id===id);if(!p||p.stock<1)return toast('This look is currently unavailable.');const item=cart.find(i=>i.id===id);if((item?.qty||0)>=Math.min(p.stock,20))return toast('You’ve reached the available quantity.');if(item)item.qty++;else cart.push({id,qty:1});saveCart();toast(p.name+' added to your bag')}
function productDetail(id){const p=products.find(p=>p.id===id);if(!p)return;$('#product-detail').innerHTML=`<div class="detail-layout"><img src="${image(p.image_url)}" alt="${esc(p.name)}"><div class="detail-copy"><span class="eyebrow">${esc(p.category)} / THE COLLECTION</span><h2 id="detail-title">${esc(p.name)}</h2><strong class="detail-price">${money(p.price_cents)}</strong><p>${esc(p.description)||'Find your next signature look in the Hairluke collection.'}</p><dl><div><dt>Texture</dt><dd>${esc(p.texture)}</dd></div><div><dt>Length</dt><dd>${esc(p.length)}</dd></div><div><dt>Colour</dt><dd>${esc(p.colour)}</dd></div></dl><p class="availability">${p.stock>0?(p.stock<=5?'Only '+p.stock+' available':'Available to order'):'Currently sold out'}</p><button class="primary" id="detail-add" ${p.stock<1?'disabled':''}>${icon('bag')} Add to bag</button><a class="save-look" href="/try-on">${icon('spark')} Explore colours on your own hair</a><button class="save-look" data-detail-fav="${esc(p.id)}" aria-pressed="${favourites.includes(p.id)}">${icon('heart')}${favourites.includes(p.id)?'Saved to favourites':'Save this look'}</button><p class="small">Delivery ${money(shipping||0)} · Payment handled securely by Yoco.</p></div></div>`;$('#detail-add').onclick=()=>addToCart(id);$('[data-detail-fav]').onclick=()=>toggleFavourite(id);$('#product-dialog').showModal()}
function applyCollectionFilters(){category=$('[data-category].active')?.dataset.category||category;renderProducts()}
function rememberOrder(token){let history;try{history=JSON.parse(localStorage.getItem('hairluke-orders')||'[]');if(!Array.isArray(history))history=[]}catch{history=[]}history=history.filter(o=>o.token!==token&&/^[a-f0-9]{64}$/.test(o.token||''));history.unshift({token,date:new Date().toISOString()});localStorage.setItem('hairluke-orders',JSON.stringify(history.slice(0,10)))}
function orderPage(){import('./account.js').then(({initAccount})=>initAccount($('#main'),{sb,esc,money,api,onSession:next=>{session=next}})).catch(()=>{$('#main').textContent='Unable to open your orders. Please refresh.'})}
function enhanceAdmin(data){
 const stats=dashboardStats(data.products,data.orders),root=$('.admin');root.classList.add('studio');
 const oldStatus=$('#admin-status');oldStatus.textContent='Your collection, orders and everyday details. All in one place.';
 const panels=[...document.querySelectorAll('#admin-content>.admin-card')];
 const settingsPanel=panels[0],editorPanel=panels[1],inventoryPanel=panels[2],ordersPanel=panels[3];
 settingsPanel.dataset.panel='settings';editorPanel.dataset.panel='products';inventoryPanel.dataset.panel='products';ordersPanel.dataset.panel='orders';
 const overview=document.createElement('section');overview.dataset.panel='overview';overview.className='overview-panel';
 overview.innerHTML=`<div class="stat-grid"><article><span>Live sales</span><strong>${money(stats.revenue)}</strong><small>Paid + shipped orders in the latest 100</small></article><article><span>Ready to fulfil</span><strong>${stats.toShip}</strong><small>Paid live orders awaiting dispatch</small></article><article><span>Active products</span><strong>${data.products.filter(p=>p.active).length}</strong><small>${data.products.length} products in your collection</small></article><article><span>Low stock</span><strong>${stats.lowStock.length}</strong><small>Visible products with 5 or fewer available</small></article></div><div class="overview-grid"><div class="admin-card"><span class="eyebrow">YOUR NEXT STEPS</span><h2>A little attention here.</h2>${stats.lowStock.length?stats.lowStock.map(p=>`<button class="stock-alert" data-stock-edit="${p.id}"><span>${esc(p.name)}<small>${esc(p.length)} · ${esc(p.colour)}</small></span><strong class="${p.stock===0?'error':''}">${p.stock===0?'Sold out':p.stock+' left'} ↗</strong></button>`).join(''):'<p class="small">Your active products have healthy stock levels.</p>'}</div><div class="admin-card"><span class="eyebrow">PAYMENT OPERATIONS</span><h2>Keep orders moving.</h2><p>${stats.pending} pending order${stats.pending===1?'':'s'} · ${stats.testOrders} test order${stats.testOrders===1?'':'s'} in the latest 100.</p><p class="small">Test orders are excluded from live sales. Pending orders reserve stock; reconcile payment status before restoring it. Refunds are managed in Yoco.</p><button class="primary" data-go-orders>Review orders ${icon('arrow')}</button></div></div>`;
 $('#admin-content').prepend(overview);
 const nav=document.createElement('nav');nav.className='studio-tabs';nav.setAttribute('aria-label','Admin sections');nav.innerHTML=['overview','products','orders','settings'].map((x,i)=>`<button data-admin-tab="${x}" class="${i===0?'active':''}">${x==='overview'?'Overview':x==='products'?'Collection':x==='orders'?'Orders':'Shop settings'}</button>`).join('');root.insertBefore(nav,$('#admin-content'));
 function switchTab(tab){if(!['overview','products','orders','settings'].includes(tab))tab='overview';sessionStorage.setItem('hairluke-admin-tab',tab);root.querySelectorAll('[data-panel]').forEach(p=>p.classList.toggle('hidden',p.dataset.panel!==tab));nav.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.adminTab===tab);b.setAttribute('aria-pressed',String(b.dataset.adminTab===tab))})}
 nav.querySelectorAll('button').forEach(b=>b.onclick=()=>switchTab(b.dataset.adminTab));$('[data-go-orders]').onclick=()=>switchTab('orders');switchTab(sessionStorage.getItem('hairluke-admin-tab')||'overview');
 const productRows=[...inventoryPanel.querySelectorAll('tbody tr')];const inventoryTools=document.createElement('div');inventoryTools.className='table-tools';inventoryTools.innerHTML='<input type="search" id="inventory-search" aria-label="Search inventory" placeholder="Search name, length or colour…"><select id="inventory-filter" aria-label="Filter inventory"><option value="all">All products</option><option value="low">Low stock (5 or less)</option><option value="hidden">Hidden products</option></select><span id="inventory-count"></span>';inventoryPanel.insertBefore(inventoryTools,inventoryPanel.querySelector('table'));
 function filterInventory(){let count=0;productRows.forEach((row,i)=>{const p=data.products[i],query=$('#inventory-search').value.toLowerCase(),mode=$('#inventory-filter').value;const show=[p.name,p.length,p.colour,p.texture].join(' ').toLowerCase().includes(query)&&(mode!=='low'||p.stock<=5)&&(mode!=='hidden'||!p.active);row.classList.toggle('hidden',!show);if(show)count++});$('#inventory-count').textContent=count+' products'}$('#inventory-search').oninput=filterInventory;$('#inventory-filter').onchange=filterInventory;filterInventory();
 productRows.forEach((row,i)=>{const p=data.products[i];const actions=row.lastElementChild;actions.insertAdjacentHTML('beforeend',`<button class="quiet-action" data-duplicate="${p.id}">Duplicate</button><button class="quiet-action" data-visibility="${p.id}">${p.active?'Hide':'Publish'}</button>`)});
 document.querySelectorAll('[data-duplicate]').forEach(b=>b.onclick=()=>{const p=data.products.find(p=>p.id===b.dataset.duplicate),form=$('#product-form');form.reset();form.elements.id.value='';for(const k of ['category','texture','length','colour','image_url','description'])form.elements[k].value=p[k]||'';form.elements.name.value=p.name.slice(0,113)+' (copy)';form.elements.price.value=p.price_cents/100;form.elements.stock.value=0;form.elements.active.checked=false;switchTab('products');editorPanel.scrollIntoView({behavior:'smooth'});toast('Draft copy ready. Review and save to create it.')});
 document.querySelectorAll('[data-visibility]').forEach(b=>b.onclick=async()=>{b.disabled=true;const p=data.products.find(p=>p.id===b.dataset.visibility);try{await api('/api/admin/products',{method:'POST',body:{...productPayload(p),active:!p.active}});await admin();switchTabAfterRefresh('products')}catch(e){toast(e.message);b.disabled=false}});
 document.querySelectorAll('[data-stock-edit]').forEach(b=>b.onclick=()=>{switchTab('products');document.querySelector('[data-edit="'+b.dataset.stockEdit+'"]').click();editorPanel.scrollIntoView({behavior:'smooth'})});
 const orderTools=document.createElement('div');orderTools.className='table-tools';orderTools.innerHTML='<input id="order-search" type="search" aria-label="Search orders" placeholder="Search reference, name or email…"><select id="order-filter" aria-label="Filter orders"><option value="all">All orders</option><option value="pending">Pending</option><option value="paid">Paid</option><option value="processing">Preparing</option><option value="shipped">Shipped</option><option value="test">Test orders</option><option value="live">Live orders</option></select><button id="refresh-admin-orders">Refresh orders</button><button id="export-orders">Export CSV</button><span id="order-count"></span>';ordersPanel.insertBefore(orderTools,ordersPanel.querySelector('table'));let filteredOrders=data.orders;const rows=[...ordersPanel.querySelectorAll('tbody tr')];function filterOrders(){filteredOrders=[];rows.forEach((row,i)=>{const o=data.orders[i],query=$('#order-search').value.toLowerCase(),filter=$('#order-filter').value;const show=[o.id,o.customer.name,o.customer.email].join(' ').toLowerCase().includes(query)&&(filter==='all'||(['test','live'].includes(filter)?o.payment_mode===filter:o.status===filter));row.classList.toggle('hidden',!show);if(show)filteredOrders.push(o)});$('#order-count').textContent=filteredOrders.length+' orders'}$('#refresh-admin-orders').onclick=async()=>{await admin();switchTabAfterRefresh('orders')};$('#order-search').oninput=filterOrders;$('#order-filter').onchange=filterOrders;filterOrders();$('#export-orders').onclick=()=>{const blob=new Blob([ordersCsv(filteredOrders)],{type:'text/csv;charset=utf-8'});const link=document.createElement('a'),href=URL.createObjectURL(blob);link.href=href;link.download='hairluke-orders-'+new Date().toISOString().slice(0,10)+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(href),1000);toast('Filtered orders exported. Keep this customer data private.')};
 const photo=$('#product-form').elements.photo;const preview=document.createElement('img');preview.className='upload-preview hidden';preview.alt='Selected product photo preview';photo.parentElement.append(preview);let previewURL;photo.onchange=()=>{if(previewURL)URL.revokeObjectURL(previewURL);const file=photo.files[0];if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){preview.classList.add('hidden');return}previewURL=URL.createObjectURL(file);preview.src=previewURL;preview.classList.remove('hidden')};
}
function switchTabAfterRefresh(name){document.querySelector('[data-admin-tab="'+name+'"]').click()}

function operationsDialog(title,content){let dialog=$('#operations-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='operations-dialog';dialog.setAttribute('aria-labelledby','operations-title');document.body.append(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}dialog.innerHTML=`<div class="dialog-inner"><div class="dialog-top"><h2 id="operations-title">${esc(title)}</h2><button class="close" id="close-operations" aria-label="Close">×</button></div>${content}</div>`;$('#close-operations').onclick=()=>dialog.close();dialog.showModal();return dialog}
function enhanceOperations(data){
 const ready=data.operations_ready===true,inventory=document.querySelector('[data-panel="products"].admin-list'),orders=document.querySelector('[data-panel="orders"]');
 if(!ready){const info=document.createElement('div');info.className='notice operations-notice';info.innerHTML='Stock history and delivery tracking need a one-time database update before use. Your existing products and orders are safe; the shop owner must run migration 002_inventory_fulfilment.sql. <a href="/setup-inventory.sql" download>Download database update</a> · <a href="https://supabase.com/dashboard/project/vckudesdksgmlwweaeze/sql/new" target="_blank" rel="noopener">Open Supabase SQL Editor</a>. Paste the downloaded SQL there and click Run, then refresh this page.';$('#admin-content').prepend(info)}
 const panel=document.createElement('div');panel.className='admin-card inventory-operations';panel.dataset.panel='products';panel.classList.toggle('hidden',sessionStorage.getItem('hairluke-admin-tab')!=='products');
 panel.innerHTML=`<span class="eyebrow">KEEP YOUR SHELVES READY</span><h2>Stock deliveries & adjustments</h2><p class="small">Record incoming supplier stock and returns, or remove damaged units. Changes are added to the current available quantity, with a history for every adjustment.</p><form id="stock-form" class="stock-form"><label>Product<select name="product_id" required ${ready?'':'disabled'}><option value="">Choose a product</option>${data.products.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.length)} · ${p.stock} available</option>`).join('')}</select></label><label>Reason<select name="reason" ${ready?'':'disabled'}><option value="received">Stock received from supplier</option><option value="returned">Returned item back in stock</option><option value="damaged">Damaged / removed</option><option value="correction">Inventory correction</option></select></label><label>Quantity<input name="quantity" type="number" min="1" max="100000" step="1" required placeholder="e.g. 10" ${ready?'':'disabled'}></label><label id="correction-direction" class="hidden">Correction direction<select name="direction"><option value="1">Add units</option><option value="-1">Remove units</option></select></label><label class="wide">Note / supplier reference<input name="note" maxlength="500" placeholder="Optional: delivery note, return reference, or reason"></label><div class="stock-summary wide" id="stock-summary" role="status">Select a product and quantity to preview the new stock level.</div><button class="primary" type="submit" ${ready?'':'disabled'}>Save stock adjustment</button><p id="stock-message" class="small" role="status"></p></form><h3 class="history-title">Recent stock movements</h3><div class="admin-list"><table><thead><tr><th>Date</th><th>Product</th><th>Reason</th><th>Change</th><th>Before → after</th><th>Note</th></tr></thead><tbody>${(data.stock_movements||[]).map(m=>`<tr><td>${new Date(m.created_at).toLocaleString('en-ZA')}</td><td>${esc(data.products.find(p=>p.id===m.product_id)?.name||'Archived product')}</td><td>${esc(m.reason)}</td><td>${m.quantity>0?'+':''}${m.quantity}</td><td>${m.stock_before} → ${m.stock_after}</td><td>${esc(m.note)}</td></tr>`).join('')}</tbody></table>${data.stock_movements?.length?'':'<p class="small">No stock adjustments recorded yet.</p>'}</div>`;
 inventory.after(panel);const form=$('#stock-form');
 function calculate(){const d=new FormData(form),p=data.products.find(p=>p.id===d.get('product_id'));const reason=d.get('reason'),units=Number(d.get('quantity'));$('#correction-direction').classList.toggle('hidden',reason!=='correction');const direction=reason==='damaged'?-1:reason==='correction'?Number(d.get('direction')):1;const quantity=units*direction;if(p&&Number.isInteger(units)&&units>0){const after=p.stock+quantity;$('#stock-summary').textContent=`${p.stock} available ${quantity>0?'+':'−'} ${units} = ${after} available after this adjustment.`;$('#stock-summary').classList.toggle('error',after<0||after>100000)}else $('#stock-summary').textContent='Select a product and quantity to preview the new stock level.';return {product:p,quantity,reason,note:d.get('note')}}
 form.addEventListener('input',calculate);form.addEventListener('change',calculate);form.onsubmit=async e=>{e.preventDefault();const value=calculate();if(!value.product)return;const after=value.product.stock+value.quantity;if(!Number.isInteger(value.quantity)||!value.quantity||after<0||after>100000){$('#stock-message').textContent='Check the quantity. Available stock cannot become negative or exceed 100,000.';return}const button=form.querySelector('button');button.disabled=true;$('#stock-message').textContent='Saving stock adjustment…';try{const result=await api('/api/admin/stock',{method:'POST',body:{product_id:value.product.id,quantity:value.quantity,reason:value.reason,note:value.note}});await admin();switchTabAfterRefresh('products');toast('Stock updated: '+result.stock_before+' → '+result.stock_after)}catch(err){$('#stock-message').textContent=err.message;button.disabled=false}};
 document.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>{const stock=$('#product-form').elements.stock;stock.readOnly=true;stock.title='Use Stock deliveries & adjustments below to change existing stock.'}));
 $('#reset-product').addEventListener('click',()=>{$('#product-form').elements.stock.readOnly=false});document.querySelectorAll('[data-duplicate]').forEach(b=>b.addEventListener('click',()=>{$('#product-form').elements.stock.readOnly=false}));
 const hint=document.createElement('p');hint.className='small stock-field-note';hint.textContent='For existing products, use Stock deliveries & adjustments to change stock safely. This field sets the initial quantity for a new product.';$('#product-form').elements.stock.parentElement.append(hint);
 const rows=[...orders.querySelectorAll('tbody tr')];rows.forEach((row,i)=>{const o=data.orders[i],cell=row.lastElementChild;const statusCell=cell.previousElementSibling;statusCell.innerHTML=`<span class="order-status status-${esc(o.status)}">${esc(o.status==='shipped'?'dispatched':o.status)}</span>${o.payment_mode==='test'?'<small class="test-label">TEST ORDER</small>':''}${o.tracking_number?`<small>${esc(o.courier||'Courier')}<br>${esc(o.tracking_number)}</small>`:''}`;cell.innerHTML=['live','test'].includes(o.payment_mode)&&o.status==='paid'?`<button data-prepare="${o.id}" ${ready?'':'disabled'}>${o.payment_mode==='test'?'Simulate preparation':'Start preparing'}</button>`:['live','test'].includes(o.payment_mode)&&o.status==='processing'?`<button data-dispatch="${o.id}" ${ready?'':'disabled'}>${o.payment_mode==='test'?'Simulate dispatch':'Dispatch order'}</button>`:['live','test'].includes(o.payment_mode)&&o.status==='shipped'?`<button data-deliver="${o.id}" ${ready?'':'disabled'}>${o.payment_mode==='test'?'Simulate delivery':'Mark delivered'}</button>`:o.status==='delivered'?`<span class="small">Delivered${o.delivered_at?'<br>'+new Date(o.delivered_at).toLocaleDateString('en-ZA'):''}</span>`:''});
 $('#order-filter').insertAdjacentHTML('beforeend','<option value="delivered">Delivered</option>');
 document.querySelectorAll('[data-prepare]').forEach(b=>b.onclick=async()=>{const o=data.orders.find(o=>o.id===b.dataset.prepare);b.disabled=true;try{await api('/api/admin/orders/'+o.id,{method:'PATCH',body:{status:'processing',simulate:o.payment_mode==='test'}});await admin();switchTabAfterRefresh('orders');toast(o.payment_mode==='test'?'Test preparation simulated. No real shipment.':'Customer can now see that preparation has started.')}catch(e){toast(e.message);b.disabled=false}});
 document.querySelectorAll('[data-dispatch]').forEach(b=>b.onclick=()=>{const o=data.orders.find(o=>o.id===b.dataset.dispatch);const dialog=operationsDialog(o.payment_mode==='test'?'Simulate dispatch — test order':'Dispatch order',`<p class="small">Reference ${esc(o.id)}. ${o.payment_mode==='test'?'This is a simulation only. Do not send a real parcel.':'Stock is already reserved; dispatch will not deduct it again.'}</p><form id="dispatch-form" class="checkout-form"><label>Courier<input name="courier" maxlength="100" placeholder="e.g. your delivery service"></label><label>Tracking number<input name="tracking_number" maxlength="100" placeholder="Optional tracking reference"></label><button class="primary wide">Confirm dispatch</button><p id="dispatch-message" class="small wide" role="status"></p></form>`);$('#dispatch-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/admin/orders/'+o.id,{method:'PATCH',body:{status:'shipped',simulate:o.payment_mode==='test',...Object.fromEntries(new FormData(e.target))}});dialog.close();await admin();switchTabAfterRefresh('orders');toast('Order dispatched.')}catch(err){$('#dispatch-message').textContent=err.message;button.disabled=false}}});
 document.querySelectorAll('[data-deliver]').forEach(b=>b.onclick=()=>{const o=data.orders.find(o=>o.id===b.dataset.deliver);const dialog=operationsDialog(o.payment_mode==='test'?'Simulate delivery — no real shipment':'Confirm delivery',`<p class="small">${o.payment_mode==='test'?'Simulate delivery for this test order. No real delivery is confirmed.':'Mark order '+esc(o.id)+' delivered only after the customer or courier confirms receipt.'} This does not change stock or payment.</p><button class="primary" id="confirm-delivery">${o.payment_mode==='test'?'Confirm simulated delivery':'Yes, delivered to customer'}</button><p id="delivery-message" class="small" role="status"></p>`);$('#confirm-delivery').onclick=async e=>{e.target.disabled=true;try{await api('/api/admin/orders/'+o.id,{method:'PATCH',body:{status:'delivered',simulate:o.payment_mode==='test'}});dialog.close();await admin();switchTabAfterRefresh('orders');toast('Order marked delivered.')}catch(err){$('#delivery-message').textContent=err.message;e.target.disabled=false}}});
}

$('#app').innerHTML=base();saveCart();$('#open-cart').onclick=()=>{if(location.pathname!=='/')return location.assign('/#collection');bag();$('#cart-dialog').showModal()};$('#close-cart').onclick=()=>$('#cart-dialog').close();$('#cart-dialog').addEventListener('click',e=>{if(e.target===$('#cart-dialog'))$('#cart-dialog').close()});if((location.hash.includes('access_token=')||location.hash.includes('error='))&&location.pathname==='/'){location.replace('/account'+location.hash)}else if(location.pathname==='/admin')admin();else if(location.pathname==='/payment')payment();else if(location.pathname==='/try-on'){$('#main').innerHTML='<p class="status section">Opening your colour studio…</p>';import('./tryon.js').then(({initTryOn})=>initTryOn($('#main'))).catch(()=>{$('#main').innerHTML='<p class="notice">The colour studio could not load. Please refresh or try another browser.</p>'})}else if(location.pathname==='/account'){import('./account.js').then(({initAccount})=>initAccount($('#main'),{sb,esc,money,api,onSession:next=>{session=next}})).catch(()=>{$('#main').textContent='Unable to load your account. Please refresh.'})}else if(location.pathname==='/orders')orderPage();else if(location.pathname==='/policies')policies();else storefront();
if(location.pathname!=='/')api('/api/config').then(c=>{$('#contact-email').textContent=c.contact_email;$('#contact-email').href='mailto:'+c.contact_email;if($('#policy-shipping'))$('#policy-shipping').textContent=money(c.shipping_cents);if($('#policy-contact')){$('#policy-contact').textContent=c.contact_email;$('#policy-contact').href='mailto:'+c.contact_email}}).catch(()=>{});

$('#close-product').onclick=()=>$('#product-dialog').close();
$('#product-dialog').addEventListener('click',e=>{if(e.target===$('#product-dialog'))$('#product-dialog').close()});
$('#open-favourites').onclick=()=>{if(location.pathname!=='/')return location.assign('/?saved=1#collection');savedOnly=!savedOnly;renderProducts();$('#collection').scrollIntoView({behavior:'smooth'})};
document.querySelector('.hero-art img')?.addEventListener('error',e=>{if(!e.target.src.endsWith('/images/hero.svg'))e.target.src='/images/hero.svg'});

const menuButton=$('#mobile-menu-toggle'), siteHeader=document.querySelector('header');
function setMenu(open){siteHeader.classList.toggle('is-menu-open',open);menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close menu':'Open menu')}
menuButton.onclick=()=>setMenu(menuButton.getAttribute('aria-expanded')!=='true');
$('#mobile-navigation').addEventListener('click',e=>{if(e.target.closest('a'))setMenu(false)});
document.addEventListener('click',e=>{if(!siteHeader.contains(e.target))setMenu(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuButton.getAttribute('aria-expanded')==='true'){setMenu(false);menuButton.focus()}});
